async function assertResponse(method, path, expectedStatus, expectedBody, expectedHeaders = {}) {
  const url = `http://localhost:3000${path}`;
  const request = new Request(url, { method });
  // Mock env and cf
  const env = {
    ASSETS: {
      fetch: async () => new Response("assets")
    }
  };
  const cf = {};

  const response = await app.fetch(request, env, cf);

  if (response.status !== expectedStatus) {
    throw new Error(`[${method} ${path}] Expected status ${expectedStatus}, got ${response.status}`);
  }

  const body = response.body ? await response.text() : "";
  if (expectedBody !== undefined) {
    if (body !== expectedBody) {
      throw new Error(`[${method} ${path}] Expected body ${JSON.stringify(expectedBody)}, got ${JSON.stringify(body)}`);
    }
